package org.openactivity.recording.corpus

import java.io.File

/** Relative paths and contents of every generated corpus file. */
internal object CorpusFiles {
    fun trackPath(sc: Scenario) = "synthetic/${sc.id}-${sc.name}.sfraw.jsonl"

    fun goldenPath(sc: Scenario) = "golden/${sc.id}.expected.json"

    /** All generated files, keyed by path relative to the corpus root. */
    fun render(): Map<String, String> {
        val out = LinkedHashMap<String, String>()
        for (sc in Scenarios.all) {
            val g = TrackGen.generate(sc)
            out[trackPath(sc)] = SfRaw.write(sc, g.events)
            out[goldenPath(sc)] = Golden.expectedJson(g)
        }
        out["manifest.yaml"] = manifest()
        return out
    }

    private fun manifest(): String = buildString {
        append("# SPDX-License-Identifier: CC0-1.0\n")
        append("# GPS golden corpus. Generated by TrackGen: do not edit by hand.\n")
        append("# Regenerate: ./gradlew :android:core:recording:generateGpsCorpus\n")
        append("version: 1\n")
        append("scenarios:\n")
        for (sc in Scenarios.all) {
            append("  - id: ${sc.id}\n")
            append("    name: ${sc.name}\n")
            append("    description: \"${sc.description}\"\n")
            append("    sport: ${sc.sport.apiName}\n")
            append("    source: synthetic\n")
            append("    generator: TrackGen\n")
            append("    seed: ${sc.seed}\n")
            append("    license: CC0-1.0\n")
            append("    tags: [${sc.tags.joinToString(", ")}]\n")
            append("    track: ${trackPath(sc)}\n")
            append("    expected: ${goldenPath(sc)}\n")
        }
    }
}

/** Writes the corpus to the directory given as the first argument. */
fun main(args: Array<String>) {
    val root = File(requireNotNull(args.firstOrNull()) { "usage: GenerateCorpus <corpus-dir>" })
    for ((path, content) in CorpusFiles.render()) {
        val file = root.resolve(path)
        file.parentFile.mkdirs()
        file.writeText(content)
        println("wrote ${file.path} (${content.length} bytes)")
    }
}
